    if len(s['prems'])<200:
        return {'IDX': float(s['pos'])}
    # rolling mean
    m=0.0
    for x in s['prems']:
        m+=x
    m/=len(s['prems'])
    dm=prem-m
    pos=s['pos']
    enter=8.0
    exit_thr=1.0
    if pos==0:
        if dm>enter:
            pos=-1
        elif dm<-enter:
            pos=1
    elif pos==1:
        if dm> -exit_thr:  # reverted above -1
            # need to check if crossed towards 0
            if dm>exit_thr or dm>0:
                pos=0
            # also if extreme opposite enter, flip
            if dm>enter:
                pos=-1
        # if still strongly negative hold
    elif pos==-1:
        if dm< exit_thr:
            if dm< -exit_thr or dm<0:
                # Actually for short, we exit when dm falls below exit
                pass
            # simplify
            if dm < 2 and dm > -2:
                # near zero
                pos=0
            if dm< -enter:
                pos=1
    # cleaner logic
    if s['pos']==1:
        if dm > 0:
            pos=0
        if dm > enter:
            pos=-1
    if s['pos']==-1:
        if dm < 0:
            pos=0
        if dm < -enter:
            pos=1
    # but avoid flip in same bar second check; recompute
    # Actually redo hysteresis properly:
    pos_prev=s['pos']
    if pos_prev==0:
        if dm>enter:
            pos=-1
        elif dm<-enter:
            pos=1
        else:
            pos=0
    elif pos_prev==1:
        if dm>0:
            pos=0
            if dm>enter:
                pos=-1
        else:
            pos=1
    elif pos_prev==-1:
        if dm<0:
            pos=0
            if dm<-enter:
                pos=1
        else:
            pos=-1
    s['pos']=pos
    return {'IDX': float(pos)}

