def signal(obs):
    st = obs.state
    prev = st.get('p', 0.0)
    try:
        ha = obs.hist('A', 'mid', 5)
        hax = obs.hist('A.X', 'mid', 5)
        hb = obs.hist('B', 'mid', 5)
        hbx = obs.hist('B.X', 'mid', 5)
        hc = obs.hist('C', 'mid', 5)
        hcx = obs.hist('C.X', 'mid', 5)
        hix = obs.hist('IDX', 'mid', 5)
    except:
        return {}
    if ha is None or hax is None or hb is None or hbx is None or hc is None or hcx is None or hix is None:
        return {}
    if len(ha) < 5 or len(hix) < 5:
        return {}
    def avg3(h):
        v1 = h[-1]; v2 = h[-2]; v3 = h[-3]
        s = 0.0
        n = 0
        if v1 == v1:
            s += v1; n += 1
        if v2 == v2:
            s += v2; n += 1
        if v3 == v3:
            s += v3; n += 1
        if n == 0:
            return float('nan')
        return s / n
    fa = (avg3(ha) + avg3(hax)) / 2.0
    fb = (avg3(hb) + avg3(hbx)) / 2.0
    fc = (avg3(hc) + avg3(hcx)) / 2.0
    ix = avg3(hix)
    if not (fa == fa and fb == fb and fc == fc and ix == ix):
        return {}
    basket = 0.3333 * fa + 0.6667 * fb + 0.1667 * fc
    prem = ix - basket
    tgt = prev
    if prev == 0.0:
        if prem > 8.0:
            tgt = -1.0
        elif prem < -8.0:
            tgt = 1.0
    else:
        if tgt > 0.0 and prem > -2.0:
            tgt = -1.0 if prem > 8.0 else 0.0
        elif tgt < 0.0 and prem < 2.0:
            tgt = 1.0 if prem < -8.0 else 0.0
    st['p'] = float(tgt)
    if tgt == prev:
        return {}
    return {'IDX': float(tgt)}

